const pages = $input.item.json.data || [];
const combined = pages.map(page => {
  return `## ${page.metadata?.title || page.url}\n${page.markdown}`;
}).join('\n\n---\n\n');

// competitor_name here carries the URL (used for Firecrawl/Serper/LLM domain-based analysis).
// The user-entered LABEL is preserved separately on Normalize Input and applied downstream.
return [{
  json: {
    competitor_name: $('Normalize Input').item.json.competitor_url,
    scraped_content: combined
  }
}];

const results = $input.item.json.organic || [];
const summary = results.map((r, i) =>
  `${i+1}. ${r.title}\n   ${r.link}\n   ${r.snippet}`
).join('\n\n');

return [{ 
  json: {
    competitor_name: $('Firecrawl - Extract Content').item.json.competitor_name,
    scraped_content: $('Firecrawl - Extract Content').item.json.scraped_content,
    serper_results: summary
  }
}];

const choice = $input.item.json.choices?.[0];
const raw = choice?.message?.content;

if (!raw) {
  throw new Error('OpenAI returned empty content. Full response: ' + JSON.stringify($input.item.json).substring(0, 300));
}

let profile;
try {
  const cleaned = raw.replace(/```json|```/g, '').trim();
  const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
  if (!jsonMatch) throw new Error('No JSON object found');
  profile = JSON.parse(jsonMatch[0]);
} catch(e) {
  throw new Error('Failed to parse: ' + e.message + ' | Raw: ' + raw.substring(0, 200));
}

// LABEL must be the user-entered Competitor Name (from Normalize Input),
// NOT the LLM/domain-derived profile.company_name. This fixes mislabeled briefings.
return [{
  json: {
    competitor_profile: profile,
    competitor_name: $('Normalize Input').item.json.competitor_name
  }
}];

const allData = $input.item.json;
const competitor = allData.competitor_name;
const scraped = allData.scraped_content;
const serper = allData.serper_results;

// Extract domain name cleanly for display
const competitorClean = competitor.replace('https://', '').replace('http://', '').replace('www.', '').split('/')[0];

const payload = {
  model: "gpt-4o-mini",
  max_tokens: 2000,
  messages: [
    {
      role: "system",
      content: `You are a competitive intelligence analyst with deep knowledge of the cybersecurity industry. 
You have two sources of information: scraped website content and search results provided below. 
IMPORTANT: If any field would be empty based on the provided content, use your own training knowledge about ${competitorClean} to fill it in. 
Never leave an array empty if you know the answer. Always make your best effort to populate every field.
Respond with valid JSON only — no markdown fences, no extra text.`
    },
    {
      role: "user",
      content: `Analyze ${competitorClean} and return ONLY this JSON structure with no other text.

CRITICAL INSTRUCTIONS:
- "flagship_models" should list their main product platforms or solutions (e.g. for CrowdStrike this would be ["Falcon Platform"])
- "product_focus_areas" should list all major product categories they sell
- "target_industries" should list industries they specifically market to
- "target_customers" should describe the types of companies/personas they sell to
- "notable_customers" should list any well-known companies that use them
- "recent_news" should list 2-3 recent notable events, funding rounds, or announcements
- "funding_info" should describe their funding status or if they are publicly traded
- If the scraped content or search results don't contain this info, use your own knowledge to fill it in

Return this exact JSON structure:
{
  "company_name": "",
  "core_positioning": "",
  "target_customers": [],
  "target_industries": [],
  "product_focus_areas": [],
  "key_themes": [],
  "category_classification": "",
  "pricing_signals": "",
  "recent_news": [],
  "funding_info": "",
  "notable_customers": [],
  "flagship_models": [],
  "api_availability": "",
  "developer_ecosystem": ""
}

WEBSITE CONTENT:
${scraped ? scraped.substring(0, 4000) : 'No scraped content available - rely on your training knowledge'}

SEARCH RESULTS:
${serper ? serper.substring(0, 2000) : 'No search results available - rely on your training knowledge'}`
    }
  ]
};

return [{ json: { payload, competitor_name: competitor } }];

const profile = $input.item.json.competitor_profile;
const competitor = $input.item.json.competitor_name;

// Clean up competitor name for display
const competitorClean = competitor.replace('https://', '').replace('http://', '').replace('www.', '').split('/')[0];

// --- Twine Share-of-Voice signals (best-effort; MUST NOT break brief generation) ---
let sovBlock = 'No Share-of-Voice data is available for this competitor yet.';
try {
  const SRK = '<REDACTED_SUPABASE_JWT>';
  const SB = 'https://addwjngdezmmnxddulll.supabase.co/rest/v1';
  const H = { apikey: SRK, Authorization: 'Bearer ' + SRK };
  const nameGuess = String(competitor || '').replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0].split('.')[0].trim();
  if (nameGuess) {
    const like = encodeURIComponent('%' + nameGuess + '%');
    const weekly = await this.helpers.httpRequest({ method: 'GET', url: SB + '/sov_weekly?company=ilike.' + like + '&select=company,week_start,overall,sentiment_pct&order=week_start.desc&limit=6', headers: H, json: true });
    const rows = Array.isArray(weekly) ? weekly : [];
    if (rows.length) {
      const company = rows[0].company;
      const latest = rows[0];
      const prev = rows.find(r => r.week_start !== latest.week_start);
      const trend = prev ? (latest.overall > prev.overall + 0.5 ? 'RISING' : (latest.overall < prev.overall - 0.5 ? 'FALLING' : 'FLAT')) : 'n/a';
      const sent = (typeof latest.sentiment_pct === 'number') ? (((latest.sentiment_pct / 100) * 6 - 3).toFixed(1)) : 'n/a';
      const likeCo = encodeURIComponent('%' + company + '%');
      let poi = [];
      try { poi = await this.helpers.httpRequest({ method: 'GET', url: SB + '/posts_of_interest?author=ilike.' + likeCo + '&select=summary,relevance_reason,date&order=date.desc&limit=6', headers: H, json: true }); } catch (e) {}
      const themes = (Array.isArray(poi) ? poi : []).map(p => '  - ' + String(p.summary || p.relevance_reason || '').slice(0, 180)).filter(s => s.trim() !== '-').join('\n');
      sovBlock = 'SOV / social signals for ' + company + ' (from the Twine Share-of-Voice tracker across the identity-security peer set):\n'
        + '- Latest weekly Share of Voice: ' + Number(latest.overall || 0).toFixed(1) + '% (recent trend: ' + trend + (prev ? (', was ' + Number(prev.overall || 0).toFixed(1) + '%') : '') + ').\n'
        + '- Sentiment of external mentions: ' + sent + ' on a -3 (very negative) to +3 (very positive) scale.\n'
        + (themes ? ('- Recent notable posts / content themes they are pushing:\n' + themes) : '- No standout posts captured recently.');
    }
  }
} catch (e) { /* SOV must never block the brief */ }

const payload = {
  model: "gpt-4o-mini",
  max_tokens: 3000,
  messages: [
    {
      role: "system",
      content: `You are a senior competitive intelligence strategist at Twine Security with deep knowledge of the cybersecurity industry.
You are analyzing a competitor profile that was automatically extracted — some fields may be incomplete or empty.
IMPORTANT: If any field in the competitor profile is empty or missing, use your own training knowledge about ${competitorClean} to fill the gaps before doing your analysis.
Never leave an array empty if you can populate it with meaningful intelligence.
Output ONLY a valid JSON object. No thinking, no reasoning, no explanation. Just the JSON.`
    },
    {
      role: "user",
      content: `Here is Twine Security's positioning:
---
Twine Security is an AI-native cybersecurity company that automates security operations workflows. Our AI employees (called Twines) handle tasks like alert triage, threat investigation, compliance tracking, and security posture management — reducing manual burden for lean security teams. We target mid-market to enterprise companies that are under-resourced in security headcount. Key differentiators: fully autonomous AI agents (not copilots), deep integrations across the security stack, and fast time-to-value.
---

Competitor profile (some fields may be incomplete — use your knowledge of ${competitorClean} to fill gaps):
${JSON.stringify(profile, null, 2)}

Twine's internal Share-of-Voice / social intelligence on this competitor — use it to judge their MARKETING strategy and momentum (which channels and content types they lean on, the themes they push, whether their mindshare is rising or falling):
${sovBlock}

CRITICAL INSTRUCTIONS FOR EACH FIELD:
- "competitor_strengths": List their genuine strongest advantages in the market — be specific, not generic
- "competitor_weaknesses": List real weaknesses or gaps, especially where Twine has an advantage
- "points_of_differentiation": List specific ways Twine Security is different or better — be concrete
- "overlap_risk_areas": List areas where both companies directly compete for the same buyers
- "threat_level": Score as LOW, MEDIUM, HIGH, or CRITICAL based on how directly they compete with Twine
- "threat_rationale": Write 2-3 sentences explaining the threat level score with specific reasoning
- "positioning_gaps_for_twine": List specific gaps or weaknesses in Twine's positioning that this competitor exposes
- "battle_card_notes": Write specific talking points a Twine salesperson could use when competing against this company — be actionable and concrete
- "marketing_strategy": Using the Share-of-Voice/social signals above (and the profile), give 3-5 SPECIFIC observations about this competitor's MARKETING strategy and momentum — the channels and content types they lean on (webinars, guides, events, thought leadership, ads, etc.), the themes/narratives they push, whether their share of voice is rising or falling, and a concrete suggested response for Twine. If no SOV data is available, infer from the profile and prefix each item with "(inferred)".

Return ONLY this JSON with no other text:
{
  "competitor_strengths": ["specific strength 1", "specific strength 2"],
  "competitor_weaknesses": ["specific weakness 1", "specific weakness 2"],
  "points_of_differentiation": ["specific differentiator 1", "specific differentiator 2"],
  "overlap_risk_areas": ["specific overlap 1", "specific overlap 2"],
  "threat_level": "HIGH",
  "threat_rationale": "detailed explanation here",
  "positioning_gaps_for_twine": ["specific gap 1", "specific gap 2"],
  "battle_card_notes": ["actionable talking point 1", "actionable talking point 2"],
  "marketing_strategy": ["specific marketing observation + Twine response 1", "specific marketing observation 2"]
}`
    }
  ]
};

return [{ json: { payload, competitor_name: competitor } }];

