// Shared normalization for BOTH triggers.
// Form trigger 'Start - Enter Competitor' puts fields at $json['Competitor Name'] / $json['Competitor URL'].
// Webhook 'Webhook - Single' puts the POSTed JSON body at $json.body (sometimes top-level).
// Output a consistent shape: { competitor_name, competitor_url } regardless of which trigger fired.
const j = $input.item.json || {};
const body = j.body || {};

const pick = (...keys) => {
  for (const src of [j, body]) {
    for (const k of keys) {
      const v = src && src[k];
      if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
    }
  }
  return '';
};

const competitor_name = pick('Competitor Name', 'competitor_name', 'competitor', 'company', 'name');
const competitor_url = pick('Competitor URL', 'competitor_url', 'url', 'URL');

if (!competitor_url) {
  throw new Error('Normalize Input: missing Competitor URL. Got keys: ' + JSON.stringify(Object.keys(j)) + ' body keys: ' + JSON.stringify(Object.keys(body)));
}

return [{ json: { competitor_name, competitor_url } }];
